// jetstream-files: validatorjs/dist/bundle.es6.min.js validatorjs/benchmark.js
// iterations: 120
// c-sources: -lpcre2-8
/* C analogue of JetStream's validatorjs row (validator.js 13.15 test suite).
 *
 * The row runs the test suite of validator.js: 10,114 assertions, each a call of one
 * validator with a value and the test's options. This analogue runs the same 10,114
 * assertions: validatorjs-data.h (generated by validatorjs-gen.py from the validator.js
 * sources and the test suite, the same ones the bundle was built from) holds every
 * case as (validator, input, options JSON, expected result) and every regular
 * expression of the library as JS source and flags.
 *
 * Each library function is a C function of the same logic: options are the JS option
 * objects (parsed from their JSON text), regular expressions are the library's own,
 * translated from JS syntax to PCRE2 (UTF mode) and JIT-compiled once, at start-up,
 * outside the timed loop, as V8 compiles the module's regex literals once. Strings are
 * UTF-8 (WTF-8 for lone surrogates); JS lengths count UTF-16 code units.
 *
 * main() runs the 10,114 assertions for ITERATIONS passes (after one warm-up pass),
 * prints the elapsed milliseconds and the assertion count, and exits 1 if any result
 * differs from the expected one. */
#define _POSIX_C_SOURCE 200809L
#define PCRE2_CODE_UNIT_WIDTH 8
#include <ctype.h>
#include <math.h>
#include <pcre2.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>

/* memmem without _GNU_SOURCE */
static const void *mem_find(const void *h, size_t hn, const void *nd, size_t nn) {
  const unsigned char *a = h, *b = nd;
  if (nn == 0) return h;
  for (size_t i = 0; i + nn <= hn; i++)
    if (a[i] == b[0] && memcmp(a + i, b, nn) == 0) return a + i;
  return NULL;
}

#include "validatorjs-data.h"

#define ITERATIONS 120

/* ------------------------------------------------------------------ JSON values */

typedef enum { J_NULL, J_BOOL, J_NUM, J_STR, J_ARR, J_OBJ } JType;
typedef struct JV JV;
struct JV {
  JType t;
  int b;
  double num;
  char *s;   /* string (WTF-8), NUL-terminated */
  size_t n;  /* byte length of s */
  JV **it;   /* array items, or object values */
  char **k;  /* object keys */
  size_t cnt;
};

static int failures;

static void die(const char *msg) {
  fprintf(stderr, "validatorjs: %s\n", msg);
  exit(1);
}

static void *xmalloc(size_t n) {
  void *p = malloc(n ? n : 1);
  if (!p) die("out of memory");
  return p;
}

static const char *jp_ws(const char *p) {
  while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
  return p;
}

static int hexval(int c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

static void put_utf8(char *o, size_t *n, unsigned long cp) {
  if (cp < 0x80) {
    o[(*n)++] = (char)cp;
  } else if (cp < 0x800) {
    o[(*n)++] = (char)(0xC0 | (cp >> 6));
    o[(*n)++] = (char)(0x80 | (cp & 0x3F));
  } else if (cp < 0x10000) {
    o[(*n)++] = (char)(0xE0 | (cp >> 12));
    o[(*n)++] = (char)(0x80 | ((cp >> 6) & 0x3F));
    o[(*n)++] = (char)(0x80 | (cp & 0x3F));
  } else {
    o[(*n)++] = (char)(0xF0 | (cp >> 18));
    o[(*n)++] = (char)(0x80 | ((cp >> 12) & 0x3F));
    o[(*n)++] = (char)(0x80 | ((cp >> 6) & 0x3F));
    o[(*n)++] = (char)(0x80 | (cp & 0x3F));
  }
}

static JV *jv_new(JType t) {
  JV *v = xmalloc(sizeof *v);
  memset(v, 0, sizeof *v);
  v->t = t;
  return v;
}

static const char *jp_value(const char *p, JV **out);

/* Parses a JSON string literal at p (p points at the quote). */
static const char *jp_string(const char *p, char **out, size_t *outn) {
  size_t len = strlen(p), n = 0;
  char *o = xmalloc(len + 1);
  p++;
  while (*p && *p != '"') {
    if (*p == '\\') {
      p++;
      switch (*p) {
        case 'n': o[n++] = '\n'; break;
        case 't': o[n++] = '\t'; break;
        case 'r': o[n++] = '\r'; break;
        case 'b': o[n++] = '\b'; break;
        case 'f': o[n++] = '\f'; break;
        case 'u': {
          unsigned long cp = 0;
          int k;
          for (k = 1; k <= 4; k++) cp = cp * 16 + (unsigned long)hexval((unsigned char)p[k]);
          p += 4;
          if (cp >= 0xD800 && cp < 0xDC00 && p[1] == '\\' && p[2] == 'u') {
            unsigned long lo = 0;
            for (k = 3; k <= 6; k++) lo = lo * 16 + (unsigned long)hexval((unsigned char)p[k]);
            if (lo >= 0xDC00 && lo < 0xE000) {
              cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
              p += 6;
            }
          }
          put_utf8(o, &n, cp);
          break;
        }
        default: o[n++] = *p; break; /* \" \\ \/ */
      }
      p++;
    } else {
      o[n++] = *p++;
    }
  }
  if (*p != '"') die("bad JSON string");
  o[n] = '\0';
  *out = o;
  *outn = n;
  return p + 1;
}

static const char *jp_value(const char *p, JV **out) {
  JV *v;
  p = jp_ws(p);
  if (*p == '"') {
    v = jv_new(J_STR);
    p = jp_string(p, &v->s, &v->n);
  } else if (*p == '[') {
    v = jv_new(J_ARR);
    p = jp_ws(p + 1);
    while (*p != ']') {
      JV *item;
      size_t i = v->cnt;
      p = jp_value(p, &item);
      v->it = realloc(v->it, (i + 1) * sizeof *v->it);
      v->it[i] = item;
      v->cnt = i + 1;
      p = jp_ws(p);
      if (*p == ',') p = jp_ws(p + 1);
    }
    p++;
  } else if (*p == '{') {
    v = jv_new(J_OBJ);
    p = jp_ws(p + 1);
    while (*p != '}') {
      char *key;
      size_t kn;
      JV *val;
      size_t i = v->cnt;
      p = jp_string(p, &key, &kn);
      p = jp_ws(p);
      if (*p != ':') die("bad JSON object");
      p = jp_value(p + 1, &val);
      v->it = realloc(v->it, (i + 1) * sizeof *v->it);
      v->k = realloc(v->k, (i + 1) * sizeof *v->k);
      v->it[i] = val;
      v->k[i] = key;
      v->cnt = i + 1;
      p = jp_ws(p);
      if (*p == ',') p = jp_ws(p + 1);
    }
    p++;
  } else if (strncmp(p, "true", 4) == 0) {
    v = jv_new(J_BOOL);
    v->b = 1;
    p += 4;
  } else if (strncmp(p, "false", 5) == 0) {
    v = jv_new(J_BOOL);
    p += 5;
  } else if (strncmp(p, "null", 4) == 0) {
    v = jv_new(J_NULL);
    p += 4;
  } else {
    char *end;
    v = jv_new(J_NUM);
    v->num = strtod(p, &end);
    if (end == p) die("bad JSON value");
    p = end;
  }
  *out = v;
  return p;
}

static JV *jv_parse(const char *text) {
  JV *v;
  jp_value(text, &v);
  return v;
}

/* object member by key; NULL when absent */
static const JV *jv_get(const JV *o, const char *key) {
  if (!o || o->t != J_OBJ) return NULL;
  for (size_t i = 0; i < o->cnt; i++)
    if (strcmp(o->k[i], key) == 0) return o->it[i];
  return NULL;
}

/* args[i] of the test's argument array; NULL when there is no such argument */
static const JV *arg(const JV *args, size_t i) {
  return (args && i < args->cnt) ? args->it[i] : NULL;
}

/* JS truthiness of a JSON value (NULL = undefined) */
static int truthy(const JV *v) {
  if (!v || v->t == J_NULL) return 0;
  switch (v->t) {
    case J_BOOL: return v->b;
    case J_NUM: return v->num != 0 && !isnan(v->num);
    case J_STR: return v->n > 0;
    default: return 1;
  }
}

static int is_str(const JV *v) { return v && v->t == J_STR; }

/* ------------------------------------------------------------------ strings */

/* JS string length (UTF-16 code units) of a UTF-8 / WTF-8 string of n bytes. */
static size_t js_len_n(const char *s, size_t n) {
  size_t units = 0;
  for (size_t i = 0; i < n; i++) {
    unsigned char c = (unsigned char)s[i];
    if ((c & 0xC0) != 0x80) units += (c >= 0xF0) ? 2 : 1;
  }
  return units;
}

static size_t js_len(const JV *v) { return is_str(v) ? js_len_n(v->s, v->n) : 0; }

/* Code points of a string as an array (WTF-8 decoded; lone surrogates kept as units). */

/* ------------------------------------------------------------------ regular expressions */

typedef struct {
  const char *name;
  pcre2_code *code;
  pcre2_match_data *md;
  int ngroups;
} Re;

static Re *re_table;
static pcre2_match_context *re_mctx;
static int re_sorted_idx[VJ_NRX];

static void re_buf_put(char **b, size_t *n, size_t *cap, const char *s, size_t len) {
  if (*n + len + 1 > *cap) {
    *cap = (*n + len + 1) * 2;
    *b = realloc(*b, *cap);
    if (!*b) die("out of memory");
  }
  memcpy(*b + *n, s, len);
  *n += len;
  (*b)[*n] = '\0';
}

static void re_put(char **b, size_t *n, size_t *cap, const char *s) { re_buf_put(b, n, cap, s, strlen(s)); }

/* Translates one JS regular expression (source text, flags) to PCRE2 syntax, UTF mode. */
static char *js_regex_to_pcre2(const char *src, const char *flags) {
  size_t len = strlen(src), i = 0, n = 0, cap = len * 4 + 64;
  char *o = xmalloc(cap);
  int in_class = 0, multi = 0, dotall = 0;
  int cls_prev = 0; /* the last item of a class is a class escape: a following '-' is a literal (JS Annex B) */
  o[0] = '\0';
  for (const char *f = flags; *f; f++) {
    if (*f == 'm') multi = 1;
    if (*f == 's') dotall = 1;
  }
  while (i < len) {
    unsigned char c = (unsigned char)src[i];
    if (c == '\\') {
      unsigned char e;
      if (i + 1 >= len) die("trailing backslash in regex");
      e = (unsigned char)src[i + 1];
      i += 2;
      switch (e) {
        case 's':
          re_put(&o, &n, &cap, in_class ? "\\t\\n\\x{0b}\\f\\r \\x{a0}\\x{1680}\\x{2000}-\\x{200a}\\x{2028}\\x{2029}\\x{202f}\\x{205f}\\x{3000}\\x{feff}"
                                        : "[\\t\\n\\x{0b}\\f\\r \\x{a0}\\x{1680}\\x{2000}-\\x{200a}\\x{2028}\\x{2029}\\x{202f}\\x{205f}\\x{3000}\\x{feff}]");
          break;
        case 'S':
          if (in_class) die("\\S inside a class is not translated");
          re_put(&o, &n, &cap, "[^\\t\\n\\x{0b}\\f\\r \\x{a0}\\x{1680}\\x{2000}-\\x{200a}\\x{2028}\\x{2029}\\x{202f}\\x{205f}\\x{3000}\\x{feff}]");
          break;
        case 'b': re_put(&o, &n, &cap, in_class ? "\\x{08}" : "\\b"); break;
        case 'B': re_put(&o, &n, &cap, "\\B"); break;
        case 'd': case 'D': case 'w': case 'W': case 'n': case 'r': case 't': case 'f':
        case 'p': case 'P':
          re_buf_put(&o, &n, &cap, "\\", 1);
          re_buf_put(&o, &n, &cap, (const char *)&e, 1);
          break;
        case 'v': re_put(&o, &n, &cap, "\\x{0b}"); break;
        case '0': re_put(&o, &n, &cap, "\\x{0}"); break;
        case 'x': {
          int v = hexval((unsigned char)src[i]) * 16 + hexval((unsigned char)src[i + 1]);
          char t[24];
          snprintf(t, sizeof t, "\\x{%x}", (unsigned)v);
          re_put(&o, &n, &cap, t);
          i += 2;
          break;
        }
        case 'u': {
          char t[32];
          if (i < len && src[i] == '{') {
            size_t j = i + 1;
            while (j < len && src[j] != '}') j++;
            snprintf(t, sizeof t, "\\x{%.*s}", (int)(j - i - 1), src + i + 1);
            i = j + 1;
          } else {
            int v = 0;
            for (int k = 0; k < 4; k++) v = v * 16 + hexval((unsigned char)src[i + (size_t)k]);
            snprintf(t, sizeof t, "\\x{%x}", (unsigned)v);
            i += 4;
          }
          re_put(&o, &n, &cap, t);
          break;
        }
        case 'c': {
          char t[24];
          snprintf(t, sizeof t, "\\x{%x}", (unsigned)((unsigned char)src[i] % 32u));
          re_put(&o, &n, &cap, t);
          i++;
          break;
        }
        default:
          if (e >= '1' && e <= '9') {
            if (in_class) die("backreference inside a class");
            re_buf_put(&o, &n, &cap, "\\", 1);
            re_buf_put(&o, &n, &cap, (const char *)&e, 1);
          } else if (isalpha(e)) {
            re_buf_put(&o, &n, &cap, (const char *)&e, 1);
          } else {
            re_buf_put(&o, &n, &cap, "\\", 1);
            re_buf_put(&o, &n, &cap, (const char *)&e, 1);
          }
          break;
      }
      cls_prev = in_class && e != 0 && strchr("sdwDWpP", e) != NULL;
      continue;
    }
    if (in_class) {
      if (c == ']') {
        in_class = 0;
        re_buf_put(&o, &n, &cap, "]", 1);
      } else if (c == '[') {
        re_put(&o, &n, &cap, "\\[");
      } else if (c == '-' && (cls_prev || (i + 2 < len && src[i + 1] == '\\' && src[i + 2] != '\0' && strchr("sdwDWS", src[i + 2]) != NULL))) {
        re_put(&o, &n, &cap, "\\-");
      } else {
        re_buf_put(&o, &n, &cap, (const char *)&c, 1);
      }
      cls_prev = 0;
      i++;
      continue;
    }
    switch (c) {
      case '[':
        if (i + 1 < len && src[i + 1] == ']') {
          re_put(&o, &n, &cap, "(?!)");
          i += 2;
          break;
        }
        if (i + 2 < len && src[i + 1] == '^' && src[i + 2] == ']') {
          re_put(&o, &n, &cap, "[\\x{0}-\\x{10ffff}]");
          i += 3;
          break;
        }
        in_class = 1;
        re_buf_put(&o, &n, &cap, "[", 1);
        i++;
        if (i < len && src[i] == '^') {
          re_buf_put(&o, &n, &cap, "^", 1);
          i++;
        }
        break;
      case '.':
        re_put(&o, &n, &cap, dotall ? "[\\x{0}-\\x{10ffff}]" : "[^\\n\\r\\x{2028}\\x{2029}]");
        i++;
        break;
      case '^':
        re_put(&o, &n, &cap, multi ? "(?:^|(?<=[\\n\\r\\x{2028}\\x{2029}]))" : "^");
        i++;
        break;
      case '$':
        re_put(&o, &n, &cap, multi ? "(?=[\\n\\r\\x{2028}\\x{2029}]|\\z)" : "\\z");
        i++;
        break;
      default:
        re_buf_put(&o, &n, &cap, (const char *)&c, 1);
        i++;
        break;
    }
  }
  return o;
}

static int re_cmp_name(const void *a, const void *b) {
  return strcmp(VJ_RX[*(const int *)a].name, VJ_RX[*(const int *)b].name);
}

/* Compiles library regex i on first use (PCRE2 translation and JIT happen outside the timed loop: the warm-up pass uses them all). */
static void re_compile_one(int i) {
  uint32_t opts = PCRE2_UTF | PCRE2_MATCH_UNSET_BACKREF;
  int err = 0;
  PCRE2_SIZE eoff = 0;
  char *pat = js_regex_to_pcre2(VJ_RX[i].src, VJ_RX[i].flags);
  for (const char *f = VJ_RX[i].flags; *f; f++)
    if (*f == 'i') opts |= PCRE2_CASELESS;
  re_table[i].name = VJ_RX[i].name;
  re_table[i].code = pcre2_compile((PCRE2_SPTR)pat, PCRE2_ZERO_TERMINATED, opts, &err, &eoff, NULL);
  if (!re_table[i].code) {
    PCRE2_UCHAR msg[256];
    pcre2_get_error_message(err, msg, sizeof msg);
    fprintf(stderr, "validatorjs: %s at %zu in /%s/ (%s)\n", (const char *)msg, (size_t)eoff, pat, VJ_RX[i].name);
    exit(1);
  }
  if (pcre2_jit_compile(re_table[i].code, PCRE2_JIT_COMPLETE) < 0) die("pcre2_jit_compile failed");
  re_table[i].md = pcre2_match_data_create_from_pattern(re_table[i].code, NULL);
  free(pat);
}

static void re_init(void) {
  re_table = xmalloc(sizeof *re_table * VJ_NRX);
  for (int i = 0; i < VJ_NRX; i++) {
    re_sorted_idx[i] = i;
    re_table[i].code = NULL;
  }
  qsort(re_sorted_idx, VJ_NRX, sizeof re_sorted_idx[0], re_cmp_name);
  re_mctx = pcre2_match_context_create(NULL);
}

/* index of the library regex with this name ("file.name" or "file.table[key]") */
static int re_index(const char *name) {
  int lo = 0, hi = VJ_NRX - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int c = strcmp(VJ_RX[re_sorted_idx[mid]].name, name);
    if (c == 0) return re_sorted_idx[mid];
    if (c < 0) lo = mid + 1;
    else hi = mid - 1;
  }
  fprintf(stderr, "validatorjs: no regex named %s\n", name);
  exit(1);
}

/* The subject for PCRE2 (UTF mode, valid UTF-8 only): a lone surrogate (WTF-8 ED A0..BF xx) is
 * matched as U+FFFD, which lies in the same JS character classes as the code unit it stands for
 * (the classes of the library never separate U+FFFD from a surrogate). */
static char *sub_buf;
static size_t sub_cap;
static const char *subject_for_pcre(const char *s, size_t n, size_t *outn) {
  int bad = 0;
  size_t m = 0;
  for (size_t i = 0; i + 1 < n; i++)
    if ((unsigned char)s[i] == 0xED && (unsigned char)s[i + 1] >= 0xA0) {
      bad = 1;
      break;
    }
  if (!bad) {
    *outn = n;
    return s;
  }
  if (sub_cap < n * 3 + 4) {
    sub_cap = n * 3 + 4;
    sub_buf = realloc(sub_buf, sub_cap);
    if (!sub_buf) die("out of memory");
  }
  for (size_t i = 0; i < n;) {
    if ((unsigned char)s[i] == 0xED && i + 2 < n && (unsigned char)s[i + 1] >= 0xA0) {
      sub_buf[m++] = (char)0xEF;
      sub_buf[m++] = (char)0xBF;
      sub_buf[m++] = (char)0xBD;
      i += 3;
    } else {
      sub_buf[m++] = s[i++];
    }
  }
  *outn = m;
  return sub_buf;
}

static int re_test_ix(int ix, const char *s, size_t n);

/* RegExp.prototype.test on the regex with this name (lastIndex 0, search anywhere). */
static int re_test(const char *name, const char *s, size_t n) {
  return re_test_ix(re_index(name), s, n);
}


/* Whole-string match: the regex with ^ and $ anchors in the library's source. */

/* ------------------------------------------------------------------ validators */

typedef int (*VFn)(const JV *in, const JV *args);

/* a RegExp argument, as the records encode it: { "$re": source, "$flags": flags } */
static int jv_is_re(const JV *v) { return v && v->t == J_OBJ && jv_get(v, "$re") != NULL; }

/* a Date argument, as the records encode it: { "$date": time value in ms } (NAN for an invalid Date) */
static int jv_is_date(const JV *v) { return v && v->t == J_OBJ && jv_get(v, "$date") != NULL; }
static double jv_date_ms(const JV *v) { return jv_get(v, "$date")->t == J_NUM ? jv_get(v, "$date")->num : NAN; }

/* ------------------------------------------------------------------ JS helpers */

/* Dynamically built regular expressions (new RegExp(...) in the library): compiled once
 * per distinct source and flag set, then kept. */
typedef struct {
  char *key;
  Re re;
} DynRe;
static DynRe dyn_re[1024];
static int ndyn_re;

static Re *dyn_compile(const char *src, const char *flags) {
  char *key;
  size_t kn = strlen(src) + strlen(flags) + 2;
  key = xmalloc(kn + 1);
  snprintf(key, kn + 1, "%s/%s", flags, src);
  for (int i = 0; i < ndyn_re; i++)
    if (strcmp(dyn_re[i].key, key) == 0) {
      free(key);
      return &dyn_re[i].re;
    }
  if (ndyn_re == (int)(sizeof dyn_re / sizeof dyn_re[0])) die("too many dynamic regexes");
  {
    DynRe *d = &dyn_re[ndyn_re++];
    uint32_t opts = PCRE2_UTF | PCRE2_MATCH_UNSET_BACKREF;
    int err = 0;
    PCRE2_SIZE eoff = 0;
    char *pat = js_regex_to_pcre2(src, flags);
    for (const char *f = flags; *f; f++)
      if (*f == 'i') opts |= PCRE2_CASELESS;
    d->key = key;
    d->re.name = key;
    d->re.code = pcre2_compile((PCRE2_SPTR)pat, PCRE2_ZERO_TERMINATED, opts, &err, &eoff, NULL);
    if (!d->re.code) {
      PCRE2_UCHAR msg[256];
      pcre2_get_error_message(err, msg, sizeof msg);
      fprintf(stderr, "validatorjs: %s at %zu in /%s/\n", (const char *)msg, (size_t)eoff, pat);
      exit(1);
    }
    if (pcre2_jit_compile(d->re.code, PCRE2_JIT_COMPLETE) < 0) die("pcre2_jit_compile failed");
    d->re.md = pcre2_match_data_create_from_pattern(d->re.code, NULL);
    free(pat);
    return &d->re;
  }
}

static int re_match_re(Re *r, const char *s, size_t n);

static int dyn_test(const char *src, const char *flags, const char *s, size_t n) {
  return re_match_re(dyn_compile(src, flags), s, n);
}

/* Decodes the code point starting at s[*i]; advances *i. */
static unsigned long cp_at(const char *s, size_t n, size_t *i) {
  unsigned char c = (unsigned char)s[*i];
  unsigned long cp;
  int extra;
  if (c < 0x80) { cp = c; extra = 0; }
  else if (c < 0xE0) { cp = c & 0x1F; extra = 1; }
  else if (c < 0xF0) { cp = c & 0x0F; extra = 2; }
  else { cp = c & 0x07; extra = 3; }
  for (int j = 1; j <= extra && *i + (size_t)j < n; j++) cp = (cp << 6) | ((unsigned char)s[*i + (size_t)j] & 0x3F);
  *i += (size_t)extra + 1;
  return cp;
}

/* JS WhiteSpace and LineTerminator code points (String.prototype.trim). */
static int js_is_space(unsigned long cp) {
  return cp == 9 || cp == 10 || cp == 11 || cp == 12 || cp == 13 || cp == 32 || cp == 0xA0 || cp == 0x1680 ||
         (cp >= 0x2000 && cp <= 0x200A) || cp == 0x2028 || cp == 0x2029 || cp == 0x202F || cp == 0x205F ||
         cp == 0x3000 || cp == 0xFEFF;
}

/* trimmed view of s: [*start, *end) in bytes */
static void js_trim_range(const char *s, size_t n, size_t *start, size_t *end) {
  size_t i = 0, e = n;
  while (i < n) {
    size_t j = i;
    if (!js_is_space(cp_at(s, n, &j))) break;
    i = j;
  }
  while (e > i) {
    size_t b = e - 1;
    while (b > i && ((unsigned char)s[b] & 0xC0) == 0x80) b--;
    size_t j = b;
    if (!js_is_space(cp_at(s, n, &j))) break;
    e = b;
  }
  *start = i;
  *end = e;
}

/* ToNumber of a string (decimal, Infinity, 0x/0o/0b integers); NAN when not numeric. */
static double js_to_number_s(const char *s, size_t n) {
  size_t a, b, i;
  const char *p;
  char *end;
  double v;
  js_trim_range(s, n, &a, &b);
  if (a == b) return 0;
  p = s + a;
  i = b - a;
  if (i > 2 && p[0] == '0' && (p[1] == 'x' || p[1] == 'X' || p[1] == 'o' || p[1] == 'O' || p[1] == 'b' || p[1] == 'B')) {
    int base = (p[1] == 'x' || p[1] == 'X') ? 16 : (p[1] == 'o' || p[1] == 'O') ? 8 : 2;
    v = 0;
    for (size_t k = 2; k < i; k++) {
      int d = hexval((unsigned char)p[k]);
      if (d < 0 || d >= base) return NAN;
      v = v * base + d;
    }
    return v;
  }
  {
    size_t k = 0;
    if (p[k] == '+' || p[k] == '-') k++;
    if (i - k == 8 && strncmp(p + k, "Infinity", 8) == 0 && k + 8 == i) return p[0] == '-' ? -INFINITY : INFINITY;
    {
      size_t digits = 0;
      while (k < i && isdigit((unsigned char)p[k])) { k++; digits++; }
      if (k < i && p[k] == '.') {
        k++;
        while (k < i && isdigit((unsigned char)p[k])) { k++; digits++; }
      }
      if (digits == 0) return NAN;
      if (k < i && (p[k] == 'e' || p[k] == 'E')) {
        size_t e0 = k;
        k++;
        if (k < i && (p[k] == '+' || p[k] == '-')) k++;
        if (k == i || !isdigit((unsigned char)p[k])) return NAN;
        (void)e0;
        while (k < i && isdigit((unsigned char)p[k])) k++;
      }
      if (k != i) return NAN;
    }
  }
  {
    char *buf = xmalloc(i + 1);
    memcpy(buf, p, i);
    buf[i] = '\0';
    v = strtod(buf, &end);
    free(buf);
  }
  return v;
}

/* ToNumber of a JSON value as the library sees it (strings are numeric text). */
static double js_to_number(const JV *v) {
  if (!v) return NAN;
  switch (v->t) {
    case J_NULL: return 0;
    case J_BOOL: return v->b ? 1 : 0;
    case J_NUM: return v->num;
    case J_STR: return js_to_number_s(v->s, v->n);
    default: return NAN;
  }
}

/* parseFloat of a string: the longest decimal prefix, NAN when there is none. */
static double js_parse_float(const char *s, size_t n) {
  size_t a, b, k = 0;
  char *buf;
  double v;
  js_trim_range(s, n, &a, &b);
  {
    const char *p = s + a;
    size_t i = b - a;
    if (i >= 8 && strncmp(p + (p[0] == '+' || p[0] == '-' ? 1 : 0), "Infinity", 8) == 0)
      return p[0] == '-' ? -INFINITY : INFINITY;
    if (k < i && (p[k] == '+' || p[k] == '-')) k++;
    {
      size_t digits = 0, st = k;
      while (k < i && isdigit((unsigned char)p[k])) { k++; digits++; }
      if (k < i && p[k] == '.') {
        size_t save = k;
        k++;
        while (k < i && isdigit((unsigned char)p[k])) { k++; digits++; }
        if (digits == 0) k = save;
      }
      if (digits == 0) return NAN;
      (void)st;
      if (k < i && (p[k] == 'e' || p[k] == 'E')) {
        size_t save = k;
        k++;
        if (k < i && (p[k] == '+' || p[k] == '-')) k++;
        if (k < i && isdigit((unsigned char)p[k])) {
          while (k < i && isdigit((unsigned char)p[k])) k++;
        } else {
          k = save;
        }
      }
      buf = xmalloc(k + 1);
      memcpy(buf, p, k);
      buf[k] = '\0';
      v = strtod(buf, NULL);
      free(buf);
      return v;
    }
  }
}

/* String.prototype.split(sep).length for a non-empty string separator (pieces). */
static size_t js_split_pieces(const char *s, size_t n, const char *sep) {
  size_t sl = strlen(sep), pieces = 1;
  if (sl == 0) return js_len_n(s, n);
  for (size_t i = 0; i + sl <= n;) {
    if (memcmp(s + i, sep, sl) == 0) {
      pieces++;
      i += sl;
    } else {
      i++;
    }
  }
  return pieces;
}

/* ASCII lower-casing into a new buffer (String.prototype.toLowerCase for the test data). */
static char *js_lower(const char *s, size_t n) {
  char *o = xmalloc(n + 1);
  for (size_t i = 0; i < n; i++) o[i] = (char)((unsigned char)s[i] < 0x80 ? tolower((unsigned char)s[i]) : s[i]);
  o[n] = '\0';
  return o;
}

/* options.hasOwnProperty(key) && !isNullOrUndefined(options[key]) */
static int opt_set(const JV *o, const char *key) {
  const JV *v = jv_get(o, key);
  return v && v->t != J_NULL;
}

/* options[key] || default: the number of a numeric option, or the default */
static double opt_num_or(const JV *o, const char *key, double def) {
  const JV *v = jv_get(o, key);
  if (!v || !truthy(v)) return def;
  return js_to_number(v);
}

/* merge(options, defaults) for a boolean option that defaults to def */
static int opt_bool(const JV *o, const char *key, int def) {
  const JV *v = jv_get(o, key);
  if (!v) return def;
  return truthy(v);
}

/* ------------------------------------------------------------------ validators: batch 1 */

/* isEmpty(str, { ignore_whitespace = false }) */
static int v_isEmpty(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  int ignore = o ? opt_bool(o, "ignore_whitespace", 0) : 0;
  if (ignore) {
    size_t a, b;
    js_trim_range(in->s, in->n, &a, &b);
    return b - a == 0;
  }
  return in->n == 0;
}

/* isLength(str, min, max) or isLength(str, { min, max, discreteLengths }) */
static int v_isLength(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  double min, max = NAN;
  int has_max;
  const JV *discrete = NULL;
  size_t len, units, pres = 0, surr = 0, i;
  if (o && o->t == J_OBJ) {
    min = opt_num_or(o, "min", 0);
    has_max = jv_get(o, "max") != NULL;
    if (has_max) max = js_to_number(jv_get(o, "max"));
    if (jv_get(o, "max") && jv_get(o, "max")->t == J_NULL) has_max = 0;
    discrete = jv_get(o, "discreteLengths");
  } else {
    const JV *a1 = arg(args, 0), *a2 = arg(args, 1);
    min = (a1 && truthy(a1)) ? js_to_number(a1) : 0;
    has_max = a2 != NULL;
    if (has_max) max = js_to_number(a2);
  }
  units = 0;
  for (i = 0; i < in->n;) {
    unsigned long cp = cp_at(in->s, in->n, &i);
    units += cp >= 0x10000 ? 2 : 1;
    if (cp == 0xFE0F || cp == 0xFE0E) pres++;
    if (cp >= 0x10000) surr++;
  }
  len = units - pres - surr;
  {
    int inside = (double)len >= min && (!has_max || (double)len <= max);
    if (inside && discrete && discrete->t == J_ARR) {
      for (size_t k = 0; k < discrete->cnt; k++)
        if (discrete->it[k]->t == J_NUM && discrete->it[k]->num == (double)len) return 1;
      return 0;
    }
    return inside;
  }
}

/* isByteLength(str, min, max) or isByteLength(str, { min, max }): UTF-8 bytes */
static int v_isByteLength(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  double min, max = NAN;
  int has_max;
  double len = (double)in->n;
  if (o && o->t == J_OBJ) {
    min = opt_num_or(o, "min", 0);
    has_max = jv_get(o, "max") != NULL && jv_get(o, "max")->t != J_NULL;
    if (has_max) max = js_to_number(jv_get(o, "max"));
  } else {
    const JV *a1 = arg(args, 0), *a2 = arg(args, 1);
    min = a1 ? js_to_number(a1) : NAN;
    has_max = a2 != NULL;
    if (has_max) max = js_to_number(a2);
  }
  return len >= min && (!has_max || len <= max);
}

/* isInt(str, { allow_leading_zeroes, min, max, lt, gt }) */
static int v_isInt(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  double v;
  int ok;
  if (!o) o = NULL;
  ok = o && jv_get(o, "allow_leading_zeroes") && jv_get(o, "allow_leading_zeroes")->t == J_BOOL && !jv_get(o, "allow_leading_zeroes")->b
           ? re_test("isInt.int", in->s, in->n)
           : re_test("isInt.intLeadingZeroes", in->s, in->n);
  if (!ok) return 0;
  v = js_to_number_s(in->s, in->n);
  if (o && opt_set(o, "min") && !(v >= js_to_number(jv_get(o, "min")))) return 0;
  if (o && opt_set(o, "max") && !(v <= js_to_number(jv_get(o, "max")))) return 0;
  if (o && opt_set(o, "lt") && !(v < js_to_number(jv_get(o, "lt")))) return 0;
  if (o && opt_set(o, "gt") && !(v > js_to_number(jv_get(o, "gt")))) return 0;
  return 1;
}

/* the decimal separator of a locale (alpha.js decimal table, VJ_DEC), or NULL */
static const char *decimal_of(const char *locale) {
  for (int k = 0; k < VJ_NDEC; k++)
    if (strcmp(VJ_DEC[k].locale, locale) == 0) return VJ_DEC[k].sep;
  return NULL;
}

/* isFloat(str, { locale, min, max }) */
static int v_isFloat(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  char pat[512];
  const char *dec = ".";
  double value;
  if (o && truthy(jv_get(o, "locale")) && is_str(jv_get(o, "locale"))) {
    dec = decimal_of(jv_get(o, "locale")->s);
    if (!dec) die("isFloat: no decimal separator for the locale");
  }
  if ((in->n == 0) || (in->n == 1 && (in->s[0] == '.' || in->s[0] == ',' || in->s[0] == '-' || in->s[0] == '+')))
    return 0;
  snprintf(pat, sizeof pat, "^(?:[-+])?(?:[0-9]+)?(?:\\%s[0-9]*)?(?:[eE][\\+\\-]?(?:[0-9]+))?$", dec);
  if (!dyn_test(pat, "", in->s, in->n)) return 0;
  {
    /* str.replace(',', '.') replaces the first comma only */
    char *t = xmalloc(in->n + 1);
    char *comma;
    memcpy(t, in->s, in->n + 1);
    comma = strchr(t, ',');
    if (comma) *comma = '.';
    value = js_parse_float(t, in->n);
    free(t);
  }
  if (o && opt_set(o, "min") && !(value >= js_to_number(jv_get(o, "min")))) return 0;
  if (o && opt_set(o, "max") && !(value <= js_to_number(jv_get(o, "max")))) return 0;
  if (o && opt_set(o, "lt") && !(value < js_to_number(jv_get(o, "lt")))) return 0;
  if (o && opt_set(o, "gt") && !(value > js_to_number(jv_get(o, "gt")))) return 0;
  return 1;
}

/* isDecimal(str, { locale = 'en-US', force_decimal = false, decimal_digits = '1,' }) */
static int v_isDecimal(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  const char *locale = "en-US", *dec, *digits = "1,";
  char pat[512];
  int force = 0;
  if (o) {
    if (truthy(jv_get(o, "locale"))) {
      if (jv_get(o, "locale")->t == J_ARR) {
        locale = jv_get(o, "locale")->it[0]->s;
      } else {
        locale = jv_get(o, "locale")->s;
      }
    }
    force = opt_bool(o, "force_decimal", 0);
    if (truthy(jv_get(o, "decimal_digits"))) digits = jv_get(o, "decimal_digits")->s;
  }
  dec = decimal_of(locale);
  if (!dec) die("isDecimal: invalid locale");
  {
    char *sp = xmalloc(in->n + 1);
    size_t m = 0;
    for (size_t i = 0; i < in->n; i++)
      if (in->s[i] != ' ') sp[m++] = in->s[i];
    sp[m] = '\0';
    if (m == 0 || (m == 1 && (sp[0] == '-' || sp[0] == '+'))) {
      free(sp);
      return 0;
    }
    free(sp);
  }
  snprintf(pat, sizeof pat, "^[-+]?([0-9]+)?(\\%s[0-9]{%s})%s$", dec, digits, force ? "" : "?");
  return dyn_test(pat, "", in->s, in->n);
}

/* isNumeric(str, { no_symbols, locale }) */
static int v_isNumeric(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  if (o && truthy(jv_get(o, "no_symbols"))) return re_test("isNumeric.numericNoSymbols", in->s, in->n);
  {
    const char *dec = ".";
    char pat[256];
    if (o && truthy(jv_get(o, "locale"))) {
      dec = decimal_of(jv_get(o, "locale")->s);
      if (!dec) die("isNumeric: invalid locale");
    }
    snprintf(pat, sizeof pat, "^[+-]?([0-9]*[%s])?[0-9]+$", dec);
    return dyn_test(pat, "", in->s, in->n);
  }
}

static int in_list(const char *s, size_t n, const char *const *list, size_t cnt) {
  for (size_t i = 0; i < cnt; i++)
    if (strlen(list[i]) == n && memcmp(list[i], s, n) == 0) return 1;
  return 0;
}

/* isBoolean(str, { loose = false }) */
static int v_isBoolean(const JV *in, const JV *args) {
  static const char *const strict[] = {"true", "false", "1", "0"};
  static const char *const loose[] = {"true", "false", "1", "0", "yes", "no"};
  const JV *o = arg(args, 0);
  if (o && opt_bool(o, "loose", 0)) {
    char *l = js_lower(in->s, in->n);
    int r = in_list(l, in->n, loose, 6);
    free(l);
    return r;
  }
  return in_list(in->s, in->n, strict, 4);
}

/* equals(str, comparison) */
static int v_equals(const JV *in, const JV *args) {
  const JV *c = arg(args, 0);
  return c && c->t == J_STR && c->n == in->n && memcmp(c->s, in->s, in->n) == 0;
}

/* contains(str, elem, { ignoreCase = false, minOccurrences = 1 }) */
static int v_contains(const JV *in, const JV *args) {
  const JV *elem = arg(args, 0), *o = arg(args, 1);
  int ignore = o ? opt_bool(o, "ignoreCase", 0) : 0;
  double minocc = o ? opt_num_or(o, "minOccurrences", 1) : 1;
  char *el = NULL, *hay;
  size_t pieces;
  if (!elem) return 0;
  if (elem->t == J_STR) {
    el = xmalloc(elem->n + 1);
    memcpy(el, elem->s, elem->n + 1);
  } else if (elem->t == J_NUM) {
    el = xmalloc(32);
    snprintf(el, 32, "%.17g", elem->num);
  } else {
    el = xmalloc(16);
    strcpy(el, elem->t == J_BOOL ? (elem->b ? "true" : "false") : "null");
  }
  if (ignore) {
    char *l = js_lower(el, strlen(el));
    free(el);
    el = l;
    hay = js_lower(in->s, in->n);
  } else {
    hay = xmalloc(in->n + 1);
    memcpy(hay, in->s, in->n);
    hay[in->n] = '\0';
  }
  pieces = js_split_pieces(hay, in->n, el);
  free(el);
  free(hay);
  return (double)pieces > minocc;
}

/* matches(str, pattern, modifiers): !!str.match(new RegExp(pattern, modifiers)) */
static int v_matches(const JV *in, const JV *args) {
  const JV *p = arg(args, 0), *m = arg(args, 1);
  const char *src = "[object Object]", *flags = "";
  char *fl = NULL;
  int r;
  if (jv_is_re(p)) {
    src = jv_get(p, "$re")->s;
    flags = jv_get(p, "$flags")->s;
  } else if (p && p->t == J_STR) src = p->s;
  else if (p && p->t == J_NUM) {
    fl = xmalloc(32);
    snprintf(fl, 32, "%.17g", p->num);
    src = fl;
  }
  if (m && m->t == J_STR) flags = m->s;
  r = dyn_test(src, flags, in->s, in->n);
  free(fl);
  return r;
}
/* ------------------------------------------------------------------ JS helpers: batch 2 */

/* Matches a regex literal of the library (JS syntax), compiled at its first use. */
#define DRX(src, flags, s, n) (__extension__ ({ static Re *rx_ = NULL; if (!rx_) rx_ = dyn_compile(src, flags); re_match_re(rx_, (s), (n)); }))

/* Matches a named regex of VJ_RX, with its index cached at the call site. */
#define RXT(name, s, n) (__extension__ ({ static int ix_ = -1; if (ix_ < 0) ix_ = re_index(name); re_test_ix(ix_, (s), (n)); }))

static int re_match_re(Re *r, const char *s0, size_t n0) {
  size_t n;
  const char *s = subject_for_pcre(s0, n0, &n);
  int rc = pcre2_match(r->code, (PCRE2_SPTR)s, (PCRE2_SIZE)n, 0, 0, r->md, re_mctx);
  if (rc == PCRE2_ERROR_NOMATCH) return 0;
  if (rc < 0) {
    fprintf(stderr, "validatorjs: pcre2_match error %d on subject [%.*s]\n", rc, (int)(n < 80 ? n : 80), s);
    exit(1);
  }
  return 1;
}

static int re_test_ix(int ix, const char *s, size_t n) {
  if (!re_table[ix].code) re_compile_one(ix);
  return re_match_re(&re_table[ix], s, n);
}

/* Group 1 of the first match of a compiled regex: [*gs, *ge) in bytes. */
static int re_group1(Re *r, const char *s0, size_t n0, size_t *gs, size_t *ge) {
  size_t n;
  const char *s = subject_for_pcre(s0, n0, &n);
  int rc = pcre2_match(r->code, (PCRE2_SPTR)s, (PCRE2_SIZE)n, 0, 0, r->md, re_mctx);
  PCRE2_SIZE *ov;
  if (rc == PCRE2_ERROR_NOMATCH) return 0;
  if (rc < 0) die("pcre2_match failed");
  ov = pcre2_get_ovector_pointer(r->md);
  *gs = ov[2];
  *ge = ov[3];
  return 1;
}

/* s.split(sep) with a one-byte separator: the number of pieces (has_sep 0: no separator) */
static size_t split_count(const char *s, size_t n, char sep, int has_sep) {
  size_t c = 1;
  if (!has_sep) return 1;
  for (size_t i = 0; i < n; i++)
    if (s[i] == sep) c++;
  return c;
}

/* piece k of s.split(sep): *start and *len */
static void split_piece(const char *s, size_t n, char sep, int has_sep, size_t k, const char **start, size_t *len) {
  size_t idx = 0, b = 0;
  *start = s + n;
  *len = 0;
  if (!has_sep) {
    *start = s;
    *len = n;
    return;
  }
  for (size_t i = 0; i <= n; i++) {
    if (i == n || s[i] == sep) {
      if (idx == k) {
        *start = s + b;
        *len = i - b;
        return;
      }
      idx++;
      b = i + 1;
    }
  }
}

/* a copy of s[0..n) as a NUL-terminated string */
static char *dup_n(const char *s, size_t n) {
  char *o = xmalloc(n + 1);
  memcpy(o, s, n);
  o[n] = '\0';
  return o;
}

/* a string option's text, or def when the value is absent or not a string */
static const char *str_or(const JV *v, const char *def) { return is_str(v) ? v->s : def; }

/* ToString of a number or boolean option value (buf holds the number text) */
static const char *jv_text(const JV *v, char *buf, size_t cap) {
  if (!v) return "";
  if (v->t == J_STR) return v->s;
  if (v->t == J_NUM) {
    if (v->num == (double)(long long)v->num) snprintf(buf, cap, "%lld", (long long)v->num);
    else snprintf(buf, cap, "%.17g", v->num);
    return buf;
  }
  if (v->t == J_BOOL) return v->b ? "true" : "false";
  return "";
}

/* parseInt(text, 10): NAN when there are no digits */
static double js_parse_int10(const char *s, size_t n) {
  size_t a, b, i;
  int neg = 0, any = 0;
  double v = 0;
  js_trim_range(s, n, &a, &b);
  i = a;
  if (i < b && (s[i] == '+' || s[i] == '-')) {
    neg = s[i] == '-';
    i++;
  }
  for (; i < b && s[i] >= '0' && s[i] <= '9'; i++) {
    v = v * 10 + (s[i] - '0');
    any = 1;
  }
  if (!any) return NAN;
  return neg ? -v : v;
}

/* days from 1970-01-01 of a proleptic Gregorian date (month 1..12; day 1.. may roll over) */
static double days_from_civil(double y, int m, double d) {
  long long yy = (long long)y - (m <= 2 ? 1 : 0);
  long long era = (yy >= 0 ? yy : yy - 399) / 400;
  long long yoe = yy - era * 400;
  long long mp = (m + 9) % 12;
  long long doy = (153 * mp + 2) / 5;
  long long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  return (double)(era * 146097 + doe - 719468) + (d - 1);
}

static int is_digit_at(const char *s, size_t n, size_t i) { return i < n && s[i] >= '0' && s[i] <= '9'; }

/* ISO 8601 date(-time) as V8 reads it; without an offset the time is UTC (the zone is UTC). */
static int date_iso(const char *s, size_t n, double *out) {
  size_t q = 0, r, t;
  int ylen = 4, sign = 1;
  double y = 0, mo = 1, d = 1, h = 0, mi = 0, sec = 0, ms = 0, off = 0;
  if (q < n && (s[q] == '+' || s[q] == '-')) {
    sign = s[q] == '-' ? -1 : 1;
    q++;
    ylen = 6;
  }
  if (q + (size_t)ylen > n) return 0;
  for (int k = 0; k < ylen; k++) {
    if (!is_digit_at(s, n, q + (size_t)k)) return 0;
    y = y * 10 + (s[q + (size_t)k] - '0');
  }
  y *= sign;
  r = q + (size_t)ylen;
  if (r < n && s[r] == '-') {
    if (!is_digit_at(s, n, r + 1) || !is_digit_at(s, n, r + 2)) return 0;
    mo = (s[r + 1] - '0') * 10 + (s[r + 2] - '0');
    r += 3;
    if (r < n && s[r] == '-') {
      if (!is_digit_at(s, n, r + 1) || !is_digit_at(s, n, r + 2)) return 0;
      d = (s[r + 1] - '0') * 10 + (s[r + 2] - '0');
      r += 3;
    }
  }
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return 0;
  t = r;
  if (t < n) {
    if (s[t] != 'T' && s[t] != 't') return 0;
    t++;
    if (!is_digit_at(s, n, t) || !is_digit_at(s, n, t + 1) || t + 2 >= n || s[t + 2] != ':' ||
        !is_digit_at(s, n, t + 3) || !is_digit_at(s, n, t + 4))
      return 0;
    h = (s[t] - '0') * 10 + (s[t + 1] - '0');
    mi = (s[t + 3] - '0') * 10 + (s[t + 4] - '0');
    t += 5;
    if (t < n && s[t] == ':') {
      if (!is_digit_at(s, n, t + 1) || !is_digit_at(s, n, t + 2)) return 0;
      sec = (s[t + 1] - '0') * 10 + (s[t + 2] - '0');
      t += 3;
      if (t < n && s[t] == '.') {
        double scale = 100;
        size_t nd = 0;
        t++;
        while (is_digit_at(s, n, t)) {
          ms += (s[t] - '0') * scale;
          scale /= 10;
          t++;
          nd++;
        }
        if (nd == 0) return 0;
      }
    }
    if (h > 24 || mi > 59 || sec > 59) return 0;
    if (t < n) {
      if (s[t] == 'Z' || s[t] == 'z') {
        t++;
      } else if (s[t] == '+' || s[t] == '-') {
        int osg = s[t] == '-' ? -1 : 1;
        if (!is_digit_at(s, n, t + 1) || !is_digit_at(s, n, t + 2) || t + 3 >= n || s[t + 3] != ':' ||
            !is_digit_at(s, n, t + 4) || !is_digit_at(s, n, t + 5))
          return 0;
        off = osg * ((s[t + 1] - '0') * 600 + (s[t + 2] - '0') * 60 + (s[t + 4] - '0') * 10 + (s[t + 5] - '0'));
        t += 6;
      }
    }
    if (t != n) return 0;
  }
  *out = days_from_civil(y, (int)mo, d) * 86400000.0 + h * 3600000.0 + mi * 60000.0 + sec * 1000.0 + ms - off * 60000.0;
  return 1;
}

/* the legacy date forms: "Thu Jan 01 1970 00:00:00 GMT+0000 (...)", "08/04/2011", "Jan 5 2011" */
static int date_legacy(const char *s, size_t n, double *out) {
  int month = -1, tz = 0, have_time = 0, ampm = 0, slash = 0;
  double h = 0, mi = 0, sec = 0, ms = 0, off = 0;
  double nums[4], dparts[3];
  int nn = 0, ndp = 0;
  size_t i = 0;
  static const char *const months[] = {"jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"};
  static const char *const days[] = {"sun", "mon", "tue", "wed", "thu", "fri", "sat"};
  while (i < n) {
    unsigned char c = (unsigned char)s[i];
    if (c == '(') {
      while (i < n && s[i] != ')') i++;
      i++;
    } else if (c == ' ' || c == ',' || c == '\t') {
      i++;
    } else if (isalpha(c)) {
      char w[16];
      size_t wl = 0;
      int k, found = 0;
      while (i < n && isalpha((unsigned char)s[i])) {
        if (wl < sizeof w - 1) w[wl++] = (char)tolower((unsigned char)s[i]);
        i++;
      }
      w[wl] = '\0';
      if (wl >= 3) {
        for (k = 0; k < 12 && !found; k++)
          if (strncmp(w, months[k], 3) == 0 && wl <= 9) {
            month = k;
            found = 1;
          }
        for (k = 0; k < 7 && !found; k++)
          if (strncmp(w, days[k], 3) == 0) found = 2;
      }
      if (found) continue;
      if (strcmp(w, "gmt") == 0 || strcmp(w, "utc") == 0 || strcmp(w, "ut") == 0 || strcmp(w, "z") == 0) {
        tz = 1;
        continue;
      }
      if (strcmp(w, "am") == 0) { ampm = 1; continue; }
      if (strcmp(w, "pm") == 0) { ampm = 2; continue; }
      return 0;
    } else if (isdigit(c)) {
      double v = 0;
      size_t st = i;
      while (is_digit_at(s, n, i)) {
        v = v * 10 + (s[i] - '0');
        i++;
      }
      if (i < n && s[i] == ':' && !have_time) {
        double mn = 0, ss = 0;
        i++;
        if (!is_digit_at(s, n, i)) return 0;
        while (is_digit_at(s, n, i)) { mn = mn * 10 + (s[i] - '0'); i++; }
        if (i < n && s[i] == ':') {
          i++;
          if (!is_digit_at(s, n, i)) return 0;
          while (is_digit_at(s, n, i)) { ss = ss * 10 + (s[i] - '0'); i++; }
          if (i < n && s[i] == '.') {
            double scale = 100;
            i++;
            while (is_digit_at(s, n, i)) { ms += (s[i] - '0') * scale; scale /= 10; i++; }
          }
        }
        h = v;
        mi = mn;
        sec = ss;
        have_time = 1;
      } else if (i < n && s[i] == '/') {
        if (ndp >= 3) return 0;
        dparts[ndp++] = v;
        slash = 1;
        i++;
      } else if (slash) {
        if (ndp >= 3) return 0;
        dparts[ndp++] = v;
      } else {
        if (nn >= 4) return 0;
        nums[nn++] = v + (i - st >= 3 ? 1000 : 0); /* a year-like number (3+ digits) is marked */
      }
    } else if ((c == '+' || c == '-') && (tz || have_time)) {
      int osg = c == '-' ? -1 : 1;
      double hh = 0, mn = 0;
      size_t st;
      i++;
      st = i;
      while (is_digit_at(s, n, i)) { hh = hh * 10 + (s[i] - '0'); i++; }
      if (i < n && s[i] == ':') {
        i++;
        while (is_digit_at(s, n, i)) { mn = mn * 10 + (s[i] - '0'); i++; }
        off = osg * (hh * 60 + mn);
      } else if (i - st == 4) {
        off = osg * ((int)(hh / 100) * 60 + (int)hh % 100);
      } else if (i - st >= 1 && i - st <= 2) {
        off = osg * hh * 60;
      } else {
        return 0;
      }
      tz = 2;
    } else {
      return 0;
    }
  }
  if (ampm == 2 && h < 12) h += 12;
  if (ampm == 1 && h == 12) h = 0;
  {
    double mo, d, y;
    if (slash) {
      if (ndp != 3 || month >= 0 || nn != 0) return 0;
      mo = dparts[0];
      d = dparts[1];
      y = dparts[2];
      if (y < 100) y += y < 50 ? 2000 : 1900;
    } else {
      int ny = 0, nd = 0;
      double dv = 1, yv = 0;
      if (month < 0) return 0;
      for (int k = 0; k < nn; k++) {
        if (nums[k] >= 1000) {
          ny++;
          yv = nums[k] - 1000;
        } else {
          nd++;
          dv = nums[k];
        }
      }
      if (ny != 1 || nd > 1) return 0;
      mo = month + 1;
      d = dv;
      y = yv;
    }
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return 0;
    if (h > 24 || mi > 59 || sec > 59) return 0;
    *out = days_from_civil(y, (int)mo, d) * 86400000.0 + h * 3600000.0 + mi * 60000.0 + sec * 1000.0 + ms - off * 60000.0;
    return 1;
  }
}

/* Date.parse: the time value in ms, NAN when the string is not a date */
static double js_date_parse(const char *s, size_t n) {
  size_t a, b;
  double t;
  js_trim_range(s, n, &a, &b);
  if (date_iso(s + a, b - a, &t)) return t;
  if (date_legacy(s + a, b - a, &t)) return t;
  return NAN;
}

/* isAfter / isBefore: the option is the comparison date or { comparisonDate } */
static int date_cmp(const JV *in, const JV *args, int after) {
  const JV *o = arg(args, 0);
  const JV *cd = NULL;
  double orig, comp;
  if (!is_str(in)) return 0;
  if (o && o->t == J_OBJ) cd = jv_get(o, "comparisonDate");
  else if (o && o->t != J_NULL) cd = o;
  orig = js_date_parse(in->s, in->n);
  if (cd && truthy(cd)) {
    if (jv_is_date(cd)) comp = jv_date_ms(cd);
    else if (!is_str(cd)) return 0;
    else comp = js_date_parse(cd->s, cd->n);
  } else {
    comp = (double)time(NULL) * 1000.0; /* Date().toString() has whole seconds */
  }
  if (isnan(orig) || isnan(comp)) return 0;
  return after ? (orig > comp) : (orig < comp);
}

static int v_isAfter(const JV *in, const JV *args) { return date_cmp(in, args, 1); }
static int v_isBefore(const JV *in, const JV *args) { return date_cmp(in, args, 0); }

/* isAbaRouting(str) */
static int v_isAbaRouting(const JV *in, const JV *args) {
  long sum = 0;
  (void)args;
  if (!is_str(in) || !RXT("isAbaRouting.isRoutingReg", in->s, in->n)) return 0;
  for (size_t i = 0; i < in->n; i++) {
    int d = in->s[i] - '0';
    sum += (i % 3 == 0) ? d * 3 : (i % 3 == 1) ? d * 7 : d;
  }
  return sum % 10 == 0;
}

/* str.replace(re, '') for a RegExp: every match when the flags have g, else the first one */
static char *re_strip(const char *s, size_t n, const char *src, const char *flags, size_t *outn) {
  int all = strchr(flags, 'g') != NULL;
  Re *r = dyn_compile(src, flags);
  char *o = xmalloc(n + 1);
  size_t m = 0, last = 0, pos = 0;
  while (pos <= n) {
    const char *t;
    size_t tn, ms, me;
    int rc;
    PCRE2_SIZE *ov;
    t = subject_for_pcre(s, n, &tn);
    rc = pcre2_match(r->code, (PCRE2_SPTR)t, (PCRE2_SIZE)tn, (PCRE2_SIZE)pos, 0, r->md, re_mctx);
    if (rc == PCRE2_ERROR_NOMATCH) break;
    if (rc < 0) die("pcre2_match failed");
    ov = pcre2_get_ovector_pointer(r->md);
    ms = ov[0];
    me = ov[1];
    memcpy(o + m, s + last, ms - last);
    m += ms - last;
    last = me;
    if (!all) break;
    pos = me == ms ? me + 1 : me;
  }
  memcpy(o + m, s + last, n - last);
  m += n - last;
  o[m] = '\0';
  *outn = m;
  return o;
}

/* isAlpha / isAlphanumeric (str, locale, { ignore }): the ignore option's characters (string) or
 * the RegExp's matches are removed first */
static int alpha_check(const JV *in, const JV *args, const char *table) {
  const JV *loc = arg(args, 0), *o = arg(args, 1);
  const JV *ign = jv_get(o, "ignore");
  const char *locale = is_str(loc) ? loc->s : "en-US";
  char name[160];
  const char *str = in->s;
  size_t sn = in->n;
  char *owned = NULL;
  int r;
  if (ign && is_str(ign)) {
    size_t m = 0;
    owned = xmalloc(in->n + 1);
    for (size_t i = 0; i < in->n; i++) {
      int drop = 0;
      for (size_t k = 0; k < ign->n; k++)
        if (ign->s[k] == in->s[i]) drop = 1;
      if (!drop) owned[m++] = in->s[i];
    }
    owned[m] = '\0';
    str = owned;
    sn = m;
  } else if (jv_is_re(ign)) {
    const JV *src = jv_get(ign, "$re"), *fl = jv_get(ign, "$flags");
    owned = re_strip(in->s, in->n, src->s, fl && is_str(fl) ? fl->s : "", &sn);
    str = owned;
  }
  snprintf(name, sizeof name, "alpha.%s[%s]", table, locale);
  r = re_test_ix(re_index(name), str, sn);
  free(owned);
  return r;
}

static int v_isAlpha(const JV *in, const JV *args) { return is_str(in) && alpha_check(in, args, "alpha"); }
static int v_isAlphanumeric(const JV *in, const JV *args) { return is_str(in) && alpha_check(in, args, "alphanumeric"); }

static int v_isAscii(const JV *in, const JV *args) { (void)args; return is_str(in) && RXT("isAscii.ascii", in->s, in->n); }
static int v_isHexadecimal(const JV *in, const JV *args) {
  (void)args;
  return is_str(in) && DRX("^(0x|0h)?[0-9A-F]+$", "i", in->s, in->n);
}
static int v_isBase58(const JV *in, const JV *args) { (void)args; return is_str(in) && RXT("isBase58.base58Reg", in->s, in->n); }
static int v_isEthereumAddress(const JV *in, const JV *args) {
  (void)args;
  return is_str(in) && RXT("isEthereumAddress.eth", in->s, in->n);
}

static const char *const ISO2_CODES[] = {"AD", "AE", "AF", "AG", "AI", "AL", "AM", "AO", "AQ", "AR", "AS", "AT", "AU", "AW", "AX", "AZ", "BA", "BB", "BD", "BE", "BF", "BG", "BH", "BI", "BJ", "BL", "BM", "BN", "BO", "BQ", "BR", "BS", "BT", "BV", "BW", "BY", "BZ", "CA", "CC", "CD", "CF", "CG", "CH", "CI", "CK", "CL", "CM", "CN", "CO", "CR", "CU", "CV", "CW", "CX", "CY", "CZ", "DE", "DJ", "DK", "DM", "DO", "DZ", "EC", "EE", "EG", "EH", "ER", "ES", "ET", "FI", "FJ", "FK", "FM", "FO", "FR", "GA", "GB", "GD", "GE", "GF", "GG", "GH", "GI", "GL", "GM", "GN", "GP", "GQ", "GR", "GS", "GT", "GU", "GW", "GY", "HK", "HM", "HN", "HR", "HT", "HU", "ID", "IE", "IL", "IM", "IN", "IO", "IQ", "IR", "IS", "IT", "JE", "JM", "JO", "JP", "KE", "KG", "KH", "KI", "KM", "KN", "KP", "KR", "KW", "KY", "KZ", "LA", "LB", "LC", "LI", "LK", "LR", "LS", "LT", "LU", "LV", "LY", "MA", "MC", "MD", "ME", "MF", "MG", "MH", "MK", "ML", "MM", "MN", "MO", "MP", "MQ", "MR", "MS", "MT", "MU", "MV", "MW", "MX", "MY", "MZ", "NA", "NC", "NE", "NF", "NG", "NI", "NL", "NO", "NP", "NR", "NU", "NZ", "OM", "PA", "PE", "PF", "PG", "PH", "PK", "PL", "PM", "PN", "PR", "PS", "PT", "PW", "PY", "QA", "RE", "RO", "RS", "RU", "RW", "SA", "SB", "SC", "SD", "SE", "SG", "SH", "SI", "SJ", "SK", "SL", "SM", "SN", "SO", "SR", "SS", "ST", "SV", "SX", "SY", "SZ", "TC", "TD", "TF", "TG", "TH", "TJ", "TK", "TL", "TM", "TN", "TO", "TR", "TT", "TV", "TW", "TZ", "UA", "UG", "UM", "US", "UY", "UZ", "VA", "VC", "VE", "VG", "VI", "VN", "VU", "WF", "WS", "YE", "YT", "ZA", "ZM", "ZW"};
#define NISO2 249


/* isBIC(str): the country code (characters 5 and 6) is an ISO 3166 alpha-2 code or XK */
static int v_isBIC(const JV *in, const JV *args) {
  int known = 0;
  (void)args;
  if (!is_str(in) || in->n < 6) return 0;
  for (size_t k = 0; k < NISO2 && !known; k++)
    if (strlen(ISO2_CODES[k]) == 2 && strncasecmp(ISO2_CODES[k], in->s + 4, 2) == 0) known = 1;
  if (!known && !(toupper((unsigned char)in->s[4]) == 'X' && toupper((unsigned char)in->s[5]) == 'K')) return 0;
  return RXT("isBIC.isBICReg", in->s, in->n);
}

/* isBase32(str, { crockford }) */
static int v_isBase32(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  if (!is_str(in)) return 0;
  if (opt_bool(o, "crockford", 0)) return RXT("isBase32.crockfordBase32", in->s, in->n);
  return js_len(in) % 8 == 0 && RXT("isBase32.base32", in->s, in->n);
}

/* isBase64(str, { urlSafe, padding }): padding defaults to !urlSafe */
static int v_isBase64(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  int url = opt_bool(o, "urlSafe", 0);
  int padding = jv_get(o, "padding") ? opt_bool(o, "padding", 0) : !url;
  int ok;
  if (!is_str(in)) return 0;
  if (in->n == 0) return 1;
  if (url) {
    ok = padding ? RXT("isBase64.base64UrlWithPadding", in->s, in->n) : RXT("isBase64.base64UrlWithoutPadding", in->s, in->n);
  } else {
    ok = padding ? RXT("isBase64.base64WithPadding", in->s, in->n) : RXT("isBase64.base64WithoutPadding", in->s, in->n);
  }
  return (!padding || js_len(in) % 4 == 0) && ok;
}

/* isBtcAddress(str) */
static int v_isBtcAddress(const JV *in, const JV *args) {
  (void)args;
  return is_str(in) && (RXT("isBtcAddress.bech32", in->s, in->n) || RXT("isBtcAddress.base58", in->s, in->n));
}

/* isEAN(str): 8, 13 or 14 digits and the check digit */
static int v_isEAN(const JV *in, const JV *args) {
  size_t len;
  long checksum = 0, rem, calc;
  int actual;
  (void)args;
  if (!is_str(in) || !RXT("isEAN.validEanRegex", in->s, in->n)) return 0;
  len = in->n;
  actual = in->s[len - 1] - '0';
  for (size_t i = 0; i + 1 < len; i++) {
    int w = (len == 8 || len == 14) ? ((i % 2 == 0) ? 3 : 1) : ((i % 2 == 0) ? 1 : 3);
    checksum += (in->s[i] - '0') * w;
  }
  rem = 10 - checksum % 10;
  calc = rem < 10 ? rem : 0;
  return actual == calc;
}

/* the Luhn check of a digit string (dashes and spaces removed); false for an empty or non-digit string */
static int luhn_ok(const char *s, size_t n) {
  size_t m = 0;
  long sum = 0;
  int dbl = 0;
  char *t = xmalloc(n + 1);
  for (size_t i = 0; i < n; i++)
    if (s[i] != '-' && s[i] != ' ') t[m++] = s[i];
  t[m] = '\0';
  if (m == 0) {
    free(t);
    return 0;
  }
  for (size_t i = m; i-- > 0;) {
    int d = t[i] - '0';
    if (d < 0 || d > 9) {
      free(t);
      return 0;
    }
    if (dbl) {
      d *= 2;
      sum += d >= 10 ? d % 10 + 1 : d;
    } else {
      sum += d;
    }
    dbl = !dbl;
  }
  free(t);
  return sum % 10 == 0;
}

static int v_isLuhnNumber(const JV *in, const JV *args) {
  (void)args;
  return is_str(in) && luhn_ok(in->s, in->n);
}

/* the card regexes in the order of the library's cards table */
static int card_regex(int k, const char *s, size_t n) {
  static const char *const src[] = {
      "^3[47][0-9]{13}$",
      "^3(?:0[0-5]|[68][0-9])[0-9]{11}$",
      "^6(?:011|5[0-9][0-9])[0-9]{12,15}$",
      "^(?:2131|1800|35\\d{3})\\d{11}$",
      "^5[1-5][0-9]{2}|(222[1-9]|22[3-9][0-9]|2[3-6][0-9]{2}|27[01][0-9]|2720)[0-9]{12}$",
      "^(6[27][0-9]{14}|^(81[0-9]{14,17}))$",
      "^(?:4[0-9]{12})(?:[0-9]{3,6})?$"};
  static Re *cache[7];
  if (!cache[k]) cache[k] = dyn_compile(src[k], "");
  return re_match_re(cache[k], s, n);
}

/* isCreditCard(card, { provider }): the provider's regex (or any), then Luhn */
static int v_isCreditCard(const JV *in, const JV *args) {
  static const char *const names[] = {"amex", "dinersclub", "discover", "jcb", "mastercard", "unionpay", "visa"};
  const JV *p = jv_get(arg(args, 0), "provider");
  char *sanitized;
  size_t m = 0;
  int ok = 0;
  if (!is_str(in)) return 0;
  sanitized = xmalloc(in->n + 1);
  for (size_t i = 0; i < in->n; i++)
    if (in->s[i] != '-' && in->s[i] != ' ') sanitized[m++] = in->s[i];
  sanitized[m] = '\0';
  if (p && truthy(p)) {
    char *low = js_lower(p->s, p->n);
    int k = -1;
    for (int j = 0; j < 7; j++)
      if (strcmp(low, names[j]) == 0) k = j;
    free(low);
    if (k < 0) die("isCreditCard: unknown provider");
    ok = card_regex(k, sanitized, m);
  } else {
    for (int j = 0; j < 7 && !ok; j++)
      ok = card_regex(j, sanitized, m);
  }
  free(sanitized);
  return ok && luhn_ok(in->s, in->n);
}

/* isDivisibleBy(str, num): toFloat(str) % parseInt(num, 10) === 0 */
static int v_isFloat(const JV *in, const JV *args);
static int v_isDivisibleBy(const JV *in, const JV *args) {
  char buf[64];
  const JV *num = arg(args, 0);
  const char *text;
  double f, div;
  if (!is_str(in) || !v_isFloat(in, NULL)) return 0;
  f = js_parse_float(in->s, in->n);
  text = jv_text(num, buf, sizeof buf);
  div = js_parse_int10(text, strlen(text));
  return fmod(f, div) == 0;
}

/* isDataURI(str) */
static int v_isDataURI(const JV *in, const JV *args) {
  const char *piece;
  size_t plen, npieces, a, b, nattr;
  char *head;
  const char *sm;
  size_t smn;
  (void)args;
  if (!is_str(in)) return 0;
  npieces = split_count(in->s, in->n, ',', 1);
  if (npieces < 2) return 0;
  split_piece(in->s, in->n, ',', 1, 0, &piece, &plen);
  js_trim_range(piece, plen, &a, &b);
  head = dup_n(piece + a, b - a);
  nattr = split_count(head, b - a, ';', 1);
  split_piece(head, b - a, ';', 1, 0, &sm, &smn);
  if (smn < 5 || strncmp(sm, "data:", 5) != 0) goto bad;
  if (smn > 5 && !RXT("isDataURI.validMediaType", sm + 5, smn - 5)) goto bad;
  for (size_t i = 1; i < nattr; i++) {
    const char *at;
    size_t atn;
    split_piece(head, b - a, ';', 1, i, &at, &atn);
    if (i == nattr - 1 && atn == 6 && strncasecmp(at, "base64", 6) == 0) continue;
    if (!RXT("isDataURI.validAttribute", at, atn)) goto bad;
  }
  for (size_t k = 1; k < npieces; k++) {
    const char *dp;
    size_t dn;
    split_piece(in->s, in->n, ',', 1, k, &dp, &dn);
    if (!RXT("isDataURI.validData", dp, dn)) goto bad;
  }
  free(head);
  return 1;
bad:
  free(head);
  return 0;
}
/* ------------------------------------------------------------------ JS helpers: batch 3 */

/* isIP patterns (lib_isIP.js): the IPv4 and IPv6 address formats of the library */
#define IP_SEG "(?:[0-9a-fA-F]{1,4})"
#define IP_V4S "(?:[0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])"
#define IP_V4 "(" IP_V4S "[.]){3}" IP_V4S
#define IP4_PATTERN "^" IP_V4 "$"
#define IP6_PATTERN                                                                                             \
  "^("                                                                                                          \
  "(?:" IP_SEG ":){7}(?:" IP_SEG "|:)|"                                                                         \
  "(?:" IP_SEG ":){6}(?:" IP_V4 "|:" IP_SEG "|:)|"                                                              \
  "(?:" IP_SEG ":){5}(?::" IP_V4 "|(:" IP_SEG "){1,2}|:)|"                                                      \
  "(?:" IP_SEG ":){4}(?:(:" IP_SEG "){0,1}:" IP_V4 "|(:" IP_SEG "){1,3}|:)|"                                    \
  "(?:" IP_SEG ":){3}(?:(:" IP_SEG "){0,2}:" IP_V4 "|(:" IP_SEG "){1,4}|:)|"                                    \
  "(?:" IP_SEG ":){2}(?:(:" IP_SEG "){0,3}:" IP_V4 "|(:" IP_SEG "){1,5}|:)|"                                    \
  "(?:" IP_SEG ":){1}(?:(:" IP_SEG "){0,4}:" IP_V4 "|(:" IP_SEG "){1,6}|:)|"                                    \
  "(?::((?::" IP_SEG "){0,5}:" IP_V4 "|(?::" IP_SEG "){1,7}|:))"                                                \
  ")(%[0-9a-zA-Z.]{1,})?$"

/* isIP(str, version): version "" (either), "4" or "6" */
static int js_is_ip(const char *s, size_t n, const char *version) {
  if (version[0] == '\0') return js_is_ip(s, n, "4") || js_is_ip(s, n, "6");
  if (strcmp(version, "4") == 0) return DRX(IP4_PATTERN, "", s, n);
  if (strcmp(version, "6") == 0) return DRX(IP6_PATTERN, "", s, n);
  return 0;
}

/* isIP(str, options): options is { version } or the version itself */
static int v_isIP(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  const JV *v = (o && o->t == J_OBJ) ? jv_get(o, "version") : (o && o->t != J_NULL ? o : NULL);
  char buf[64];
  const char *version = jv_text(v, buf, sizeof buf);
  if (!is_str(in)) return 0;
  if (!truthy(v)) version = "";
  return js_is_ip(in->s, in->n, version);
}

/* isFQDN(str, { require_tld, allow_underscores, ignore_max_length }); the other options are false */
static int js_is_fqdn(const char *s, size_t n, int require_tld, int allow_underscores, int ignore_max_length, int allow_numeric_tld) {
  size_t parts = split_count(s, n, '.', 1);
  const char *tld;
  size_t tldn;
  split_piece(s, n, '.', 1, parts - 1, &tld, &tldn);
  if (require_tld) {
    if (parts < 2) return 0;
    if (!allow_numeric_tld && !DRX("^([a-z\\u00A1-\\u00A8\\u00AA-\\uD7FF\\uF900-\\uFDCF\\uFDF0-\\uFFEF]{2,}|xn[a-z0-9-]{2,})$", "i", tld, tldn)) return 0;
    if (DRX("\\s", "", tld, tldn)) return 0;
  }
  if (!allow_numeric_tld && DRX("^\\d+$", "", tld, tldn)) return 0;
  for (size_t k = 0; k < parts; k++) {
    const char *p;
    size_t pn;
    split_piece(s, n, '.', 1, k, &p, &pn);
    if (js_len_n(p, pn) > 63 && !ignore_max_length) return 0;
    if (!DRX("^[a-z_\\u00a1-\\uffff0-9-]+$", "i", p, pn)) return 0;
    if (DRX("[\\uff01-\\uff5e]", "", p, pn)) return 0;
    if (DRX("^-|-$", "", p, pn)) return 0;
    if (!allow_underscores && DRX("_", "", p, pn)) return 0;
  }
  return 1;
}

static int v_isFQDN(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  int trailing = opt_bool(o, "allow_trailing_dot", 0);
  int wildcard = opt_bool(o, "allow_wildcard", 0);
  const char *s;
  size_t n;
  if (!is_str(in)) return 0;
  s = in->s;
  n = in->n;
  if (trailing && n > 0 && s[n - 1] == '.') n--;
  if (wildcard && n >= 2 && s[0] == '*' && s[1] == '.') {
    s += 2;
    n -= 2;
  }
  return js_is_fqdn(s, n, opt_bool(o, "require_tld", 1), opt_bool(o, "allow_underscores", 0),
                    opt_bool(o, "ignore_max_length", 0), opt_bool(o, "allow_numeric_tld", 0));
}

/* isDate(input, options) of the library, for string input */
static int date_format_ok(const char *f, size_t n) { return DRX("(^(y{4}|y{2})[.\\/-](m{1,2})[.\\/-](d{1,2})$)|(^(m{1,2})[.\\/-](d{1,2})[.\\/-]((y{4}|y{2})$))|(^(d{1,2})[.\\/-](m{1,2})[.\\/-]((y{4}|y{2})$))", "gi", f, n); }

static int all_digits(const char *s, size_t n) {
  if (n == 0) return 0;
  for (size_t i = 0; i < n; i++)
    if (!isdigit((unsigned char)s[i])) return 0;
  return 1;
}

static int strict_of(const JV *args) { return opt_bool(arg(args, 0), "strictMode", 0); }

static int v_isDate(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  static const char *const dflt[] = {"/", "-"};
  const char *format;
  size_t fn;
  int strict;
  char *fmt = NULL;
  char *fmtlow;
  const JV *delims;
  const char *delim_list[2];
  size_t ndelim = 2;
  const char *formatDelim = NULL, *dateDelim = NULL;
  char dy[8] = "", dm[8] = "", dd[8] = "";
  size_t dyn = 0, dmn = 0, ddn = 0;
  int have_y = 0, have_m = 0, have_d = 0;
  int ok = 0;
  if (jv_is_date(in)) return !strict_of(args) && !isnan(jv_date_ms(in)); /* Object.prototype.toString + isFinite */
  if (!is_str(in)) return 0; /* other non-strings are not dates: the library answers false */
  if (o && o->t == J_STR) {
    fmt = dup_n(o->s, o->n);
    format = fmt;
    fn = o->n;
    strict = 0;
    delim_list[0] = dflt[0];
    delim_list[1] = dflt[1];
  } else {
    const JV *f = jv_get(o, "format");
    if (f && is_str(f)) {
      format = f->s;
      fn = f->n;
    } else {
      format = "YYYY/MM/DD";
      fn = strlen(format);
    }
    strict = opt_bool(o, "strictMode", 0);
    delim_list[0] = dflt[0];
    delim_list[1] = dflt[1];
  }
  delims = jv_get(o, "delimiters");
  if (delims && delims->t == J_ARR) {
    ndelim = delims->cnt;
    for (size_t k = 0; k < ndelim && k < 2; k++) delim_list[k] = delims->it[k]->s;
  }
  fmtlow = js_lower(format, fn);
  if (!date_format_ok(format, fn)) {
    free(fmtlow);
    free(fmt);
    return 0;
  }
  if (strict && in->n != fn) {
    free(fmtlow);
    free(fmt);
    return 0;
  }
  for (size_t k = 0; k < ndelim; k++)
    if (strstr(format, delim_list[k])) {
      formatDelim = delim_list[k];
      break;
    }
  if (strict) {
    dateDelim = formatDelim;
  } else {
    for (size_t k = 0; k < ndelim; k++)
      if (strstr(in->s, delim_list[k])) {
        dateDelim = delim_list[k];
        break;
      }
  }
  {
    /* zip(input.split(dateDelim), format.toLowerCase().split(formatDelim)) */
    size_t dcount = split_count(in->s, in->n, dateDelim ? dateDelim[0] : 0, dateDelim != NULL);
    size_t fcount = split_count(fmtlow, strlen(fmtlow), formatDelim ? formatDelim[0] : 0, formatDelim != NULL);
    size_t len = dcount > fcount ? dcount : fcount;
    ok = 1;
    for (size_t k = 0; k < len && ok; k++) {
      const char *dw = "", *fw = "";
      size_t dwn = 0, fwn = 0;
      if (k < dcount) split_piece(in->s, in->n, dateDelim ? dateDelim[0] : 0, dateDelim != NULL, k, &dw, &dwn);
      else ok = 0;
      if (k < fcount) split_piece(fmtlow, strlen(fmtlow), formatDelim ? formatDelim[0] : 0, formatDelim != NULL, k, &fw, &fwn);
      else ok = 0;
      if (!ok || dwn == 0 || fwn == 0 || dwn != fwn) {
        ok = 0;
        break;
      }
      switch (fw[0]) {
        case 'y': memcpy(dy, dw, dwn < 7 ? dwn : 7); dy[dwn < 7 ? dwn : 7] = '\0'; dyn = dwn; have_y = 1; break;
        case 'm': memcpy(dm, dw, dwn < 7 ? dwn : 7); dm[dwn < 7 ? dwn : 7] = '\0'; dmn = dwn; have_m = 1; break;
        case 'd': memcpy(dd, dw, dwn < 7 ? dwn : 7); dd[dwn < 7 ? dwn : 7] = '\0'; ddn = dwn; have_d = 1; break;
        default: break;
      }
    }
  }
  free(fmtlow);
  free(fmt);
  if (!ok || !have_y || !have_m || !have_d) return 0;
  {
    /* the year: a 4-digit year, or 2 digits: 20 when below the current year's last two digits, else 19 */
    char year[8];
    char month[4], day[4];
    if (dy[0] == '-') return 0;
    if (dyn == 2) {
      if (!all_digits(dy, 2)) return 0;
      {
        int parsed = (dy[0] - '0') * 10 + (dy[1] - '0');
        time_t now = time(NULL);
        int cur = (gmtime(&now)->tm_year + 1900) % 100;
        snprintf(year, sizeof year, "%s%s", parsed < cur ? "20" : "19", dy);
      }
    } else {
      if (dyn != 4 || !all_digits(dy, 4)) return 0;
      snprintf(year, sizeof year, "%s", dy);
    }
    if (dmn == 1) snprintf(month, sizeof month, "0%s", dm);
    else snprintf(month, sizeof month, "%s", dm);
    if (ddn == 1) snprintf(day, sizeof day, "0%s", dd);
    else snprintf(day, sizeof day, "%s", dd);
    if (!all_digits(month, 2) || !all_digits(day, 2)) return 0;
    {
      int mo = (month[0] - '0') * 10 + (month[1] - '0');
      int dv = (day[0] - '0') * 10 + (day[1] - '0');
      int yv = (int)strtol(year, NULL, 10);
      int dim;
      static const int mdays[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
      if (mo < 1 || mo > 12) return 0;
      dim = mdays[mo - 1];
      if (mo == 2 && ((yv % 4 == 0 && yv % 100 != 0) || yv % 400 == 0)) dim = 29;
      if (dv < 1 || dv > dim) return 0;
      return 1;
    }
  }
}

/* checkHost(host, matches): an entry equal to the host, or a RegExp that matches it */
static int check_host(const char *host, size_t hn, const JV *list) {
  if (!list || list->t != J_ARR) return 0;
  for (size_t k = 0; k < list->cnt; k++) {
    const JV *m = list->it[k];
    if (is_str(m) && m->n == hn && memcmp(m->s, host, hn) == 0) return 1;
    if (jv_is_re(m)) {
      const JV *src = jv_get(m, "$re"), *fl = jv_get(m, "$flags");
      if (dyn_test(src->s, fl && is_str(fl) ? fl->s : "", host, hn)) return 1;
    }
  }
  return 0;
}

/* isEmail(str, options) */

/* validateDisplayName(display_name) */
static int validate_display_name(const char *dn, size_t n) {
  const char *inner = dn;
  size_t innern = n;
  size_t quotes = 0, bs_quotes = 0, illegal = 0;
  if (n >= 3 && dn[0] == '"' && dn[n - 1] == '"') {
    inner = dn + 1;
    innern = n - 2;
  }
  {
    int blank = 1;
    for (size_t i = 0; i < innern; i++)
      if (!js_is_space((unsigned char)inner[i])) blank = 0;
    if (blank) return 0;
  }
  for (size_t i = 0; i < innern; i++) {
    if (strchr(".\";<>", inner[i]) && inner[i] != '\0') illegal = 1;
    if (inner[i] == '"') {
      quotes++;
      if (i > 0 && inner[i - 1] == '\\') bs_quotes++;
    }
  }
  if (illegal) {
    if (innern == n) return 0;
    if (quotes != bs_quotes) return 0;
  }
  return 1;
}

static int v_isEmail(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  int allow_display = opt_bool(o, "allow_display_name", 0);
  int require_display = opt_bool(o, "require_display_name", 0);
  int utf8 = opt_bool(o, "allow_utf8_local_part", 1);
  int require_tld = opt_bool(o, "require_tld", 1);
  int ignore_max = opt_bool(o, "ignore_max_length", 0);
  int allow_underscores = opt_bool(o, "allow_underscores", 0);
  int allow_ip_domain = opt_bool(o, "allow_ip_domain", 0);
  int dsv = opt_bool(o, "domain_specific_validation", 0);
  const char *blacklisted = str_or(jv_get(o, "blacklisted_chars"), "");
  const JV *blacklist = jv_get(o, "host_blacklist");
  const JV *whitelist = jv_get(o, "host_whitelist");
  const char *s;
  size_t n;
  char *dname = NULL;
  size_t at, dom_n, user_n, low_n;
  char *user = NULL, *domain = NULL, *lower_domain = NULL;
  int result = 0;
  if (!is_str(in)) return 0;
  s = in->s;
  n = in->n;
  if (require_display || allow_display) {
    size_t gs, ge;
    Re *split = NULL;
    static Re *split_re = NULL;
    (void)split;
    if (!split_re) split_re = dyn_compile("^([^\\x00-\\x1F\\x7F-\\x9F\\cX]+)<", "i");
    if (re_group1(split_re, s, n, &gs, &ge)) {
      size_t dnl = ge;
      size_t rest_start = ge;
      size_t rest_n = n - ge;
      /* str.replace(display_name, '') then strip a leading '<' and a trailing '>' */
      if (rest_n > 0 && s[rest_start] == '<') {
        rest_start++;
        rest_n--;
      }
      if (rest_n > 0 && s[rest_start + rest_n - 1] == '>') rest_n--;
      if (dnl > 0 && s[dnl - 1] == ' ') dnl--;
      dname = dup_n(s, dnl);
      if (!validate_display_name(dname, dnl)) {
        free(dname);
        return 0;
      }
      free(dname);
      dname = NULL;
      s = s + rest_start;
      n = rest_n;
    } else if (require_display) {
      return 0;
    }
  }
  if (!ignore_max && js_len_n(s, n) > 254) return 0;
  at = n;
  for (size_t i = 0; i < n; i++)
    if (s[i] == '@') at = i;
  if (at == n) {
    user_n = 0;
    dom_n = n;
    domain = dup_n(s, n);
  } else {
    user_n = at;
    dom_n = n - at - 1;
    user = dup_n(s, at);
    domain = dup_n(s + at + 1, dom_n);
  }
  if (!user) user = dup_n("", 0);
  lower_domain = js_lower(domain, dom_n);
  low_n = dom_n;
  if (check_host(lower_domain, dom_n, blacklist)) goto done;
  if (whitelist && whitelist->t == J_ARR && whitelist->cnt > 0 && !check_host(lower_domain, dom_n, whitelist)) goto done;
  if (dsv && (strcmp(lower_domain, "gmail.com") == 0 || strcmp(lower_domain, "googlemail.com") == 0)) {
    char *low = js_lower(user, user_n);
    char *username;
    size_t un, stripped_n = 0;
    const char *ps;
    size_t pn;
    size_t k;
    free(user);
    user = low;
    user_n = strlen(user);
    un = 0;
    while (un < user_n && user[un] != '+') un++;
    username = dup_n(user, un);
    {
      char *st = xmalloc(un + 1);
      for (size_t i = 0; i < un; i++)
        if (username[i] != '.') st[stripped_n++] = username[i];
      st[stripped_n] = '\0';
      if (stripped_n < 6 || stripped_n > 30) {
        free(st);
        free(username);
        goto done;
      }
      free(st);
    }
    for (k = 0; k < split_count(username, un, '.', 1); k++) {
      split_piece(username, un, '.', 1, k, &ps, &pn);
      if (!RXT("isEmail.gmailUserPart", ps, pn)) {
        free(username);
        goto done;
      }
    }
    free(username);
  }
  if (!ignore_max && (user_n > 64 || dom_n > 254)) goto done;
  if (!js_is_fqdn(domain, dom_n, require_tld, allow_underscores, ignore_max, 0)) {
    if (!allow_ip_domain) goto done;
    if (!js_is_ip(domain, dom_n, "")) {
      if (dom_n < 2 || domain[0] != '[' || domain[dom_n - 1] != ']') goto done;
      if (dom_n - 2 == 0 || !js_is_ip(domain + 1, dom_n - 2, "")) goto done;
    }
  }
  (void)low_n;
  if (blacklisted[0] != '\0') {
    char *pat = xmalloc(strlen(blacklisted) + 4);
    sprintf(pat, "[%s]+", blacklisted);
    if (dyn_test(pat, "g", user, user_n)) {
      free(pat);
      goto done;
    }
    free(pat);
  }
  if (user_n > 0 && user[0] == '"' && user[user_n - 1] == '"') {
    size_t inner_n = user_n >= 2 ? user_n - 2 : 0;
    char *inner = dup_n(user_n >= 2 ? user + 1 : user, inner_n);
    result = utf8 ? RXT("isEmail.quotedEmailUserUtf8", inner, inner_n) : RXT("isEmail.quotedEmailUser", inner, inner_n);
    free(inner);
    goto done;
  }
  {
    const char *ps;
    size_t pn;
    result = 1;
    for (size_t k = 0; k < split_count(user, user_n, '.', 1); k++) {
      split_piece(user, user_n, '.', 1, k, &ps, &pn);
      if (!(utf8 ? RXT("isEmail.emailUserUtf8Part", ps, pn) : RXT("isEmail.emailUserPart", ps, pn))) {
        result = 0;
        break;
      }
    }
  }
done:
  free(dname);
  free(user);
  free(domain);
  free(lower_domain);
  return result;
}

/* isCurrency(str, options): the pattern of lib_isCurrency.js, built per call */
typedef struct { char *s; size_t n, cap; } CBuf;
static void cb_put(CBuf *b, const char *s) { re_buf_put(&b->s, &b->n, &b->cap, s, strlen(s)); }
static void cb_putn(CBuf *b, const char *s, size_t n) { re_buf_put(&b->s, &b->n, &b->cap, s, n); }

static int v_isCurrency(const JV *in, const JV *args) {
  const JV *o = arg(args, 0);
  const char *symbol = str_or(jv_get(o, "symbol"), "$");
  int require_symbol = opt_bool(o, "require_symbol", 0);
  int space_after_symbol = opt_bool(o, "allow_space_after_symbol", 0);
  int symbol_after_digits = opt_bool(o, "symbol_after_digits", 0);
  int allow_negatives = opt_bool(o, "allow_negatives", 1);
  int parens = opt_bool(o, "parens_for_negatives", 0);
  int neg_before = opt_bool(o, "negative_sign_before_digits", 0);
  int neg_after = opt_bool(o, "negative_sign_after_digits", 0);
  int neg_placeholder = opt_bool(o, "allow_negative_sign_placeholder", 0);
  const char *thousands = str_or(jv_get(o, "thousands_separator"), ",");
  const char *decimal = str_or(jv_get(o, "decimal_separator"), ".");
  int allow_decimal = opt_bool(o, "allow_decimal", 1);
  int require_decimal = opt_bool(o, "require_decimal", 0);
  int space_after_digits = opt_bool(o, "allow_space_after_digits", 0);
  const JV *digits = jv_get(o, "digits_after_decimal");
  CBuf dd = {NULL, 0, 0}, sym = {NULL, 0, 0}, pat = {NULL, 0, 0}, tmp = {NULL, 0, 0};
  int ok;
  if (!is_str(in)) return 0;
  if (!digits || digits->t != J_ARR) {
    static JV two;
    static JV *dflt_arr = NULL;
    if (!dflt_arr) {
      dflt_arr = xmalloc(sizeof *dflt_arr);
      dflt_arr->t = J_ARR;
      dflt_arr->cnt = 1;
      dflt_arr->it = xmalloc(sizeof *dflt_arr->it);
      two.t = J_NUM;
      two.num = 2;
      dflt_arr->it[0] = &two;
    }
    digits = dflt_arr;
  }
  for (size_t k = 0; k < digits->cnt; k++) {
    char num[32];
    snprintf(num, sizeof num, "%d", (int)digits->it[k]->num);
    if (k == 0) {
      cb_put(&dd, "\\d{");
    } else {
      cb_put(&dd, "|\\d{");
    }
    cb_put(&dd, num);
    cb_put(&dd, "}");
  }
  /* symbol: the first non-word character is escaped */
  {
    size_t sn = strlen(symbol);
    int escaped = 0;
    cb_put(&sym, "(");
    for (size_t i = 0; i < sn; i++) {
      unsigned char c = (unsigned char)symbol[i];
      if (!escaped && !(c < 0x80 && (isalnum(c) || c == '_'))) {
        if (c < 0x80) cb_put(&sym, "\\");
        escaped = 1;
      }
      cb_putn(&sym, symbol + i, 1);
    }
    cb_put(&sym, require_symbol ? ")" : ")?");
  }
  /* pattern = whole + decimal */
  cb_put(&pat, "(0|[1-9]\\d*|[1-9]\\d{0,2}(\\");
  cb_put(&pat, thousands);
  cb_put(&pat, "\\d{3})*)?");
  if (allow_decimal || require_decimal) {
    cb_put(&pat, "(\\");
    cb_put(&pat, decimal);
    cb_put(&pat, "(");
    cb_putn(&pat, dd.s, dd.n);
    cb_put(&pat, "))");
    cb_put(&pat, require_decimal ? "" : "?");
  }
  if (allow_negatives && !parens) {
    if (neg_after) {
      cb_put(&pat, "-?");
    } else if (neg_before) {
      tmp.n = 0;
      cb_put(&tmp, "-?");
      cb_putn(&tmp, pat.s, pat.n);
      free(pat.s);
      pat = tmp;
      tmp = (CBuf){NULL, 0, 0};
    }
  }
  if (neg_placeholder) {
    tmp = (CBuf){NULL, 0, 0};
    cb_put(&tmp, "( (?!\\-))?");
    cb_putn(&tmp, pat.s, pat.n);
    free(pat.s);
    pat = tmp;
    tmp = (CBuf){NULL, 0, 0};
  } else if (space_after_symbol) {
    tmp = (CBuf){NULL, 0, 0};
    cb_put(&tmp, " ?");
    cb_putn(&tmp, pat.s, pat.n);
    free(pat.s);
    pat = tmp;
    tmp = (CBuf){NULL, 0, 0};
  } else if (space_after_digits) {
    cb_put(&pat, "( (?!$))?");
  }
  if (symbol_after_digits) {
    cb_putn(&pat, sym.s, sym.n);
  } else {
    tmp = (CBuf){NULL, 0, 0};
    cb_putn(&tmp, sym.s, sym.n);
    cb_putn(&tmp, pat.s, pat.n);
    free(pat.s);
    pat = tmp;
    tmp = (CBuf){NULL, 0, 0};
  }
  if (allow_negatives) {
    if (parens) {
      tmp = (CBuf){NULL, 0, 0};
      cb_put(&tmp, "(\\(");
      cb_putn(&tmp, pat.s, pat.n);
      cb_put(&tmp, "\\)|");
      cb_putn(&tmp, pat.s, pat.n);
      cb_put(&tmp, ")");
      free(pat.s);
      pat = tmp;
      tmp = (CBuf){NULL, 0, 0};
    } else if (!(neg_before || neg_after)) {
      tmp = (CBuf){NULL, 0, 0};
      cb_put(&tmp, "-?");
      cb_putn(&tmp, pat.s, pat.n);
      free(pat.s);
      pat = tmp;
      tmp = (CBuf){NULL, 0, 0};
    }
  }
  {
    CBuf full = {NULL, 0, 0};
    cb_put(&full, "^(?!-? )(?=.*\\d)");
    cb_putn(&full, pat.s, pat.n);
    cb_put(&full, "$");
    ok = dyn_test(full.s, "", in->s, in->n);
    free(full.s);
  }
  free(dd.s);
  free(sym.s);
  free(pat.s);
  free(tmp.s);
  return ok;
}
