/* a compiled regex literal (JS syntax), compiled at its first use */
#define DRE(src, flags) (__extension__ ({ static Re *r_ = NULL; if (!r_) r_ = dyn_compile(src, flags); r_; }))

/* String.prototype.replace(re, repl) with the g flag: repl is the text, or group 1 when g1 */
static void re_replace_all(Re *r, const char *s, size_t n, const char *repl, int g1, char **out, size_t *outn) {
  size_t cap = n * 2 + 16, m = 0, last = 0, pos = 0;
  char *o = xmalloc(cap);
  o[0] = '\0';
  while (pos <= n) {
    int rc = pcre2_match(r->code, (PCRE2_SPTR)s, (PCRE2_SIZE)n, (PCRE2_SIZE)pos, 0, r->md, re_mctx);
    PCRE2_SIZE *ov;
    size_t ms, me;
    if (rc == PCRE2_ERROR_NOMATCH) break;
    if (rc < 0) die("pcre2_match failed");
    ov = pcre2_get_ovector_pointer(r->md);
    ms = ov[0];
    me = ov[1];
    re_buf_put(&o, &m, &cap, s + last, ms - last);
    if (g1) re_buf_put(&o, &m, &cap, s + ov[2], ov[3] - ov[2]);
    else re_buf_put(&o, &m, &cap, repl, strlen(repl));
    last = me;
    pos = me == ms ? me + 1 : me;
  }
  re_buf_put(&o, &m, &cap, s + last, n - last);
  *out = o;
  *outn = m;
}

/* membership of s in a list of codes; upper: s is upper-cased first (ASCII) */
static int set_has(const char *const *arr, size_t cnt, const char *s, size_t n, int upper) {
  for (size_t k = 0; k < cnt; k++) {
    size_t l = strlen(arr[k]);
    if (l != n) continue;
    int eq = 1;
    for (size_t i = 0; i < n && eq; i++) {
      unsigned char c = (unsigned char)s[i];
      if (upper && c < 0x80) c = (unsigned char)toupper(c);
      if (c != (unsigned char)arr[k][i]) eq = 0;
    }
    if (eq) return 1;
  }
  return 0;
}

