#define N_TAX_CHECK 35

/* isTaxID(str, locale = 'en-US'): lib_isTaxID.js; an unknown locale is an error in the library (false here) */
static int v_isTaxID(const JV *in, const JV *args) {
  const JV *lo = arg(args, 0);
  const char *loc = "en-US";
  static Re *fmt_re[N_TAX_FMT];
  int fi = -1, ci = -1, si = -1;
  char *own = NULL;
  Str t;
  int ok;
  if (!is_str(in)) return 0;
  if (lo && lo->t != J_NULL) {
    if (!is_str(lo)) return 0;
    loc = lo->s;
  }
  for (int k = 0; k < N_TAX_FMT; k++)
    if (strcmp(TAX_FMT[k].locale, loc) == 0) {
      fi = k;
      break;
    }
  if (fi < 0) return 0;
  for (int k = 0; k < N_TAX_SANITIZE; k++)
    if (strcmp(TAX_SANITIZE[k].locale, loc) == 0) si = k;
  for (int k = 0; k < N_TAX_CHECK; k++)
    if (strcmp(TAX_CHECK[k].locale, loc) == 0) ci = k;
  t = S_of(in->s, in->n);
  if (si >= 0) {
    size_t m;
    char *r = re_strip(t.s, t.n, TAX_SANITIZE[si].src, TAX_SANITIZE[si].flags, &m);
    own = r;
    t = S_of(r, m);
  }
  if (!fmt_re[fi]) fmt_re[fi] = dyn_compile(TAX_FMT[fi].src, TAX_FMT[fi].flags);
  ok = re_match_re(fmt_re[fi], t.s, t.n);
  if (ok && ci >= 0) ok = TAX_CHECK[ci].check(t);
  free(own);
  return ok;
}
